   240	 * Get the current address from addresses array
   241	 *
   242	 * @param privatePersonalDetails - details object
   243	 * @returns - current address object
   244	 */
   245	function getCurrentAddress(privatePersonalDetails: OnyxEntry<PrivatePersonalDetails>): Address | undefined {
   246	    const {addresses} = privatePersonalDetails ?? {};
   247	    const currentAddress = addresses?.find((address) => address.current);
   248	    return currentAddress ?? addresses?.[addresses.length - 1];
   249	}
