   251	/**
   252	 * Formats an address object into an easily readable string
   253	 *
   254	 * @param privatePersonalDetails - details object
   255	 * @returns - formatted address
   256	 */
   257	function getFormattedAddress(privatePersonalDetails: OnyxEntry<PrivatePersonalDetails>): string {
   258	    const address = getCurrentAddress(privatePersonalDetails);
   259	    const [street1, street2] = getStreetLines(address?.street);
   260	    const formattedAddress =
   261	        formatPiece(street1) + formatPiece(street2) + formatPiece(address?.city) + formatPiece(address?.state) + formatPiece(address?.zip) + formatPiece(address?.country);
   262	
   263	    // Remove the last comma of the address
   264	    return formattedAddress.trim().replace(/,$/, '');
   265	}
