   267	/**
   268	 * @param personalDetail - details object
   269	 * @returns - The effective display name
   270	 */
   271	function getEffectiveDisplayName(personalDetail?: PersonalDetails): string | undefined {
   272	    if (personalDetail) {
   273	        return LocalePhoneNumber.formatPhoneNumber(personalDetail?.login ?? '') || personalDetail.displayName;
   274	    }
   275	
   276	    return undefined;
