   279	/**
   280	 * Creates a new displayName for a user based on passed personal details or login.
   281	 */
   282	function createDisplayName(login: string, passedPersonalDetails: Pick<PersonalDetails, 'firstName' | 'lastName'> | OnyxInputOrEntry<PersonalDetails>): string {
   283	    // If we have a number like +15857527441@expensify.sms then let's remove @expensify.sms and format it
   284	    // so that the option looks cleaner in our UI.
   285	    const userLogin = LocalePhoneNumber.formatPhoneNumber(login);
   286	
   287	    if (!passedPersonalDetails) {
   288	        return userLogin;
   289	    }
   290	
   291	    const firstName = passedPersonalDetails.firstName ?? '';
   292	    const lastName = passedPersonalDetails.lastName ?? '';
   293	    const fullName = `${firstName} ${lastName}`.trim();
   294	
   295	    // It's possible for fullName to be empty string, so we must use "||" to fallback to userLogin.
   296	    return fullName || userLogin;
   297	}
