   299	/**
   300	 * Gets the first and last name from the user's personal details.
   301	 * If the login is the same as the displayName, then they don't exist,
   302	 * so we return empty strings instead.
   303	 */
   304	function extractFirstAndLastNameFromAvailableDetails({login, displayName, firstName, lastName}: PersonalDetails): FirstAndLastName {
   305	    // It's possible for firstName to be empty string, so we must use "||" to consider lastName instead.
   306	    // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   307	    if (firstName || lastName) {
   308	        return {firstName: firstName ?? '', lastName: lastName ?? ''};
   309	    }
   310	    if (login && Str.removeSMSDomain(login) === displayName) {
   311	        return {firstName: '', lastName: ''};
   312	    }
   313	
   314	    if (displayName) {
   315	        const firstSpaceIndex = displayName.indexOf(' ');
   316	        const lastSpaceIndex = displayName.lastIndexOf(' ');
   317	        if (firstSpaceIndex === -1) {
   318	            return {firstName: displayName, lastName: ''};
   319	        }
   320	
   321	        return {
   322	            firstName: displayName.substring(0, firstSpaceIndex).trim(),
   323	            lastName: displayName.substring(lastSpaceIndex).trim(),
   324	        };
   325	    }
   326	
   327	    return {firstName: '', lastName: ''};
   328	}
