   341	function getUserNameByEmail(email: string, nameToDisplay: 'firstName' | 'displayName') {
   342	    const userDetails = getPersonalDetailByEmail(email);
   343	    if (userDetails) {
   344	        return userDetails[nameToDisplay] ? userDetails[nameToDisplay] : userDetails.login;
   345	    }
   346	    return email;
